// PROTOTYPE C — Outline tree (the film as a document) + production Board (every shot visible) + inspector drawer. No page changes for shot work.
function treeItem(label,st,onclick,active,indent,note){const ic={done:'●',prog:'◐',todo:'○',skipped:'↷',bypassed:'⤼',optional:'◌',defer:'◌'}[st]||'';const col={done:'var(--ok)',prog:'var(--warn)'}[st]||'#999';
 return `<div onclick="${onclick}" title="${note||''}" style="padding:3px 8px 3px ${8+indent*14}px;cursor:pointer;border-radius:5px;${active?'background:#e6ebfc;':''}${['skipped','bypassed'].includes(st)?'color:#7a7f90;font-style:italic;':''}"><span style="color:${col}">${ic}</span> ${label}${['skipped','bypassed'].includes(st)?` <span class="sm">· ${st==='bypassed'?'bypassed':'skipped'}</span>`:''}</div>`}
function viewC(){
 const mid=STATE!=='new';
 const f=U.filter;
 const sceneRows=SCENES.filter(s=>f==='all'||s.shots.some(x=>['failed','review'].includes(x.st)||x.stale)).map(s=>{
  const open=U.scene===s.i;
  return treeItem(`${s.n}. ${s.title} <span class="mut sm">${s.shots.length||'–'}</span>`,s.shots.length&&scProg(s).selected===s.shots.length?'done':s.shots.length?'prog':'todo',`go({view:'scene',scene:${s.i},shot:null,cTab:'doc'})`,U.view==='scene'&&open,1)+(open?s.shots.map(x=>treeItem(`<span class="mut">${x.id}</span> ${x.title} <i class="dot" style="background:${SHOT_STATES[x.st][1]};width:7px;height:7px"></i>`,'',`go({shot:'${x.id}'},1)`,U.shot===x.id,2)).join(''):'')}).join('');
 const tree=`<div class="scroll" style="width:270px;background:#fff;border-right:1px solid var(--line);padding:8px"><div class="sm mut" style="padding:4px 8px">${mid?'THE LANDLORD SKETCH':'UNTITLED PROJECT'}</div>
  ${treeItem('Project overview',  'prog',"go({view:'home',scene:null,shot:null})",U.view==='home',0)}
  <div class="sm mut" style="padding:8px 8px 2px">STORY</div>${PHASES.filter(p=>p.grp==='story').map(p=>treeItem(p.n,phSt(p.id),`go({view:'${p.id}',scene:null,shot:null})`,U.view===p.id,1,PH_NOTE[p.id])).join('')}
  <div class="sm mut" style="padding:8px 8px 2px">WORLD</div>${treeItem('World Definition',phSt('world'),"go({view:'world',scene:null,shot:null})",U.view==='world',1)}
  <div class="row sm mut" style="padding:8px 8px 2px">SCENES <span class="sp"></span><a style="cursor:pointer;color:var(--acc)" onclick="go({filter:'${f==='all'?'attn':'all'}'},1)">${f==='all'?'show needs-attention':'show all'}</a></div>${mid?sceneRows:'<div class="sm mut" style="padding:2px 14px">Scenes appear here once the Master Narrative is accepted.</div>'}
  <div class="sm mut" style="padding:8px 8px 2px">OUTPUT</div>${treeItem('Review & Export',phSt('review'),"go({view:'review'})",U.view==='review',1)}</div>`;
 const tabs=mid?`<div class="row" style="padding:8px 14px;background:#fff;border-bottom:1px solid var(--line)">${[['doc','Document'],['board','Board'],['review','Review']].map(([k,l])=>`<button class="${U.cTab===k?'pri':''}" onclick="go({cTab:'${k}',view:'${k==='doc'&&['home'].includes(U.view)?'home':U.view}'},1)">${l}</button>`).join('')}<span class="sp"></span>${runtimeMeter()}${filmProgress()}${staleNote()}</div>`:'';
 let main;
 if(!mid)main=onboardC();
 else if(U.cTab==='board')main=boardC();
 else if(U.cTab==='review')main=`<div class="scroll" style="flex:1">${reviewPage()}</div>`;
 else if(U.view==='home')main=boardC();
 else if(U.view==='scene')main=sceneDocC();
 else main=`<div class="scroll" style="flex:1">${phasePage(U.view)}</div>`;
 const insp=(U.shot&&shotById(U.shot))?`<div class="scroll" style="width:390px;background:#fff;border-left:1px solid var(--line)"><div class="row" style="padding:8px 14px"><span class="sm mut">INSPECTOR</span><span class="sp"></span><button class="ghost" onclick="go({shot:null},1)">✕</button></div>${shotDetail(shotById(U.shot))}</div>`:'';
 return `<div style="display:flex;flex:1;min-height:0">${tree}<div style="flex:1;display:flex;flex-direction:column;min-width:0">${tabs}${main}</div>${insp}</div>`}
function onboardC(){return `<div class="scroll" style="flex:1"><div class="pad" style="max-width:760px;margin:30px auto"><h1 style="margin:0">Start with what you have.</h1><p class="mut">The outline on the left is your film. It starts nearly empty and grows as you work — each document appears when it exists, and nothing is locked in advance.</p>
 <div class="card pad"><textarea style="width:100%;height:110px;border:1px solid var(--line);border-radius:6px;padding:8px" placeholder="Paste a paragraph, notes, a treatment, a beat sheet or a screenplay — or drop files here."></textarea><div class="row" style="margin-top:8px"><button>Upload files</button><button>Record / transcript</button><span class="sp"></span><button class="pri" onclick="alert('Prototype: Aiuteur would identify the material, show the proposed entry point for confirmation, then open the Interview')">Continue — Aiuteur reads it first</button></div></div>
 <div class="banner" style="margin-top:12px">What happens next: Aiuteur tells you what it thinks each piece is and where it should enter. You confirm. Phases your material covers appear in the outline as <i>bypassed</i> — intentional, not broken.</div></div></div>`}
function boardC(){
 return `<div class="scroll" style="flex:1"><div class="pad"><div class="row" style="margin-bottom:8px"><h3 style="margin:0">Production board</h3><span class="mut sm">every shot in the film · click a square to inspect it without leaving</span><span class="sp"></span><button>Draft plans for 2 scenes</button><button>Generate all approved…</button></div>
 <div class="row sm" style="gap:12px;flex-wrap:wrap;margin-bottom:8px">${legend()}<span class="stale">possibly out of date</span></div>
 <table style="width:100%;border-collapse:collapse;background:#fff" class="card">${SCENES.map(s=>{const t=scProg(s);return `<tr style="border-bottom:1px solid var(--line)"><td style="padding:5px 10px;width:230px;cursor:pointer;white-space:nowrap" onclick="go({view:'scene',scene:${s.i},cTab:'doc'})"><b>${s.n}</b> ${s.title}</td><td style="width:60px" class="mut sm">${fmt(s.dur)}</td><td>${s.shots.length?s.shots.map(x=>sq(x)).join(''):'<span class="mut sm">no shot plan — <u>draft</u></span>'}</td><td class="sm mut" style="width:130px;text-align:right;padding-right:10px">${s.shots.length?`${t.selected||0}/${s.shots.length} selected`:''}</td></tr>`}).join('')}</table></div></div>`}
function sceneDocC(){const s=SCENES[U.scene];
 return `<div class="scroll" style="flex:1"><div class="pad" style="max-width:860px"><div class="row"><h2 style="margin:0">Scene ${s.n}: ${s.title}</h2><span class="mut">${s.slug}</span><span class="sp"></span><button>Play scene</button></div>
 <div class="card pad" style="margin:10px 0"><div class="sm mut">MASTER NARRATIVE — this scene</div><p>${SHOT_TEXT.action} The landlord’s voice carries over from the hallway: “${SHOT_TEXT.dialogue.slice(6)}” …</p>${s.i<6?'<div class="sm mut">Editing here marks this scene’s shots possibly out of date; nothing is rewritten.</div>':''}</div>
 <div class="row" style="margin-bottom:6px"><b>Shots</b><span class="mut sm">${s.shots.length} · inline under the text they come from</span><span class="sp"></span><button>Draft shot plan</button><button>Generate approved…</button></div>
 ${s.shots.map(sh=>`<div class="card row" style="padding:6px 10px;margin:4px 0;cursor:pointer;${U.shot===sh.id?'outline:2px solid var(--acc)':''}" onclick="go({shot:'${sh.id}'},1)">${thumb(sh,64,36)}<b>${sh.id}</b><span>${sh.title}</span><span class="mut sm">${sh.dur}s</span><span class="sp"></span><span class="chip" style="border-color:${SHOT_STATES[sh.st][1]}">${SHOT_STATES[sh.st][0]}</span>${sh.stale?'<span class="stale">?</span>':''}</div>`).join('')||'<div class="banner">No shot plan yet.</div>'}</div></div>`}
